import path from "node:path";
import type { PgliteDatabase } from "drizzle-orm/pglite";
import { migrate as migratePglite } from "drizzle-orm/pglite/migrator";
import type { PostgresJsDatabase } from "drizzle-orm/postgres-js";
import { migrate as migratePostgres } from "drizzle-orm/postgres-js/migrator";
import { type Db, driverOf } from "./client";

/** Folder of SQL migrations generated by drizzle-kit (shared by both drivers). */
export const MIGRATIONS_FOLDER = path.join(process.cwd(), "drizzle");

/** Apply ./drizzle/*.sql using the drizzle migrator for the active driver. */
export async function runMigrations(db: Db): Promise<void> {
  const config = { migrationsFolder: MIGRATIONS_FOLDER };
  if (driverOf(db) === "pglite") {
    await migratePglite(db as unknown as PgliteDatabase<Record<string, unknown>>, config);
  } else {
    await migratePostgres(db as unknown as PostgresJsDatabase<Record<string, unknown>>, config);
  }
}
